  "A {0} fee of {1} {2} is in the price.": "En {0}-avgift på {1} {2} ingår i priset.",
  "A banned phone or card cannot open a new account.": "En spärrad telefon eller ett spärrat kort kan inte öppna ett nytt konto.",
  "A button that goes straight to the driver, ride, payment or zone.": "En knapp som går direkt till föraren, resan, betalningen eller zonen.",
  "A card payment of {0} failed": "En kortbetalning på {0} misslyckades",
  "A concert or a match: draw the area and set the time. During the event, these dispatch rules apply in that area.": "En konsert eller en match: rita området och ange tiden. Under evenemanget gäller de här trafikreglerna i området.",
  "A driver 18 min from the pickup gets Leave now {0} before pickup ({1}).": "En förare 18 min från upphämtningen får Åk nu {0} före upphämtningen ({1}).",
  "A driver about to drop off a rider can get the next request, as an Exclusive offer only. Never Radar during a trip.": "En förare som snart lämnar av en resenär kan få nästa förfrågan, bara som exklusivt erbjudande. Aldrig radar under en resa.",
  "A driver can't hold two rides at the same or a close time. They see them all, but once they take one, the others that do not fit the smart gap leave their Scheduled rides.": "En förare kan inte ha två resor vid samma eller närliggande tid. Hen ser alla, men när hen tar en försvinner de som inte passar det smarta mellanrummet från Bokade resor.",
  "A driver cancel this close to pickup is a late cancel. The driver still pays nothing.": "En föraravbokning så nära upphämtningen är en sen avbokning. Föraren betalar fortfarande inget.",
  "A driver ending a ride close to the pickup can take it next.": "En förare som avslutar en resa nära upphämtningen kan ta den härnäst.",
  "a driver group": "en förargrupp",
  "A driver group": "En förargrupp",
  "A driver is on the way, waiting or driving the rider.": "En förare är på väg, väntar eller kör resenären.",
  "A driver is on the way, waiting or driving.": "En förare är på väg, väntar eller kör.",
  "A driver who closes the Home popup can get the ride again as an Exclusive offer, when it reaches the Exclusive step.": "En förare som stänger popupen på startsidan kan få resan igen som exklusivt erbjudande när den når steget Exklusiv.",
  "A driver who does not accept offers is set offline, so riders are not kept waiting.": "En förare som inte accepterar erbjudanden sätts offline, så att resenärer inte får vänta.",
  "A driver's late cancel": "En förares sena avbokning",
  "A failed payment; rides blocked until paid": "En misslyckad betalning; resor spärrade tills den är betald",
  "A female rider can ask for a female driver.": "En kvinnlig resenär kan be om en kvinnlig förare.",
  "A flat price instead of km and min": "Ett fast pris i stället för km och min",
  "A group or riders by name": "En grupp eller resenärer efter namn",
  "A hole needs at least 3 points inside the zone.": "Ett hål behöver minst 3 punkter inom zonen.",
  "A manual surge lasts between 5 min and 12 h.": "Ett manuellt rusningspris varar mellan 5 min och 12 h.",
  "A random group of drivers in the zone, as many as you set. A new group is picked for each reservation.": "En slumpvis grupp förare i zonen, så många du anger. En ny grupp väljs för varje bokning.",
  "A reason is required.": "Ett skäl krävs.",
  "A refund waits for approval": "En återbetalning väntar på godkännande",
  "A refund, or a driver pay change, above this amount waits for a second admin. One limit per country, used by Payments, Trips, Riders and the server. Defaults: above {0} kr, {1} € and {2} DT.": "En återbetalning eller ändrad förarersättning över detta belopp väntar på en andra admin. En gräns per land, används av Betalningar, Resor, Resenärer och servern. Standard: över {0} kr, {1} € och {2} DT.",
  "A request for this is already waiting for a second admin.": "En begäran om detta väntar redan på en andra admin.",
  "A ride booked for later. Its free wait is the included waiting of the reservation policy.": "En resa bokad till senare. Dess gratis väntan är den inkluderade väntan i bokningspolicyn.",
  "A ride counts when": "En resa räknas när",
  "A ride Movera gives to a driver always says “Assigned by Movera”.": "En resa som Movera ger en förare visar alltid ”Tilldelad av Movera”.",
  "A ride payment failed": "En resebetalning misslyckades",
  "A ride starts in {0} and ends in another zone. What happens?": "En resa börjar i {0} och slutar i en annan zon. Vad händer?",
  "A ride with no driver this close to pickup needs attention.": "En resa utan förare så nära upphämtningen behöver uppmärksamhet.",
  "A rider and a driver can be in different zones. Drivers are matched across zone borders.": "En resenär och en förare kan vara i olika zoner. Förare matchas över zongränser.",
  "A rider and a driver who reported each other never meet again.": "En resenär och en förare som har rapporterat varandra möts aldrig igen.",
  "A rider waits too long": "En resenär väntar för länge",
  "A rider with an unpaid ride above the amount cannot book until it is paid.": "En resenär med en obetald resa över beloppet kan inte boka förrän den är betald.",
  "A run above this total waits until another admin approves it.": "En körning över denna summa väntar tills en annan admin godkänner den.",
