  "Every {0} min smart surge compares {1} with {2} (online and not on a trip). Many drivers and few requests means no surge. It starts only when a level holds for {3} min, goes down one step at a time, waits {4} min between changes, and stops by itself when the level stays low for {5} min.": "Var {0}:e minut jämför smart rusningspris {1} med {2} (online och inte på resa). Många förare och få förfrågningar betyder inget rusningspris. Det startar först när en nivå håller i {3} min, går ner ett steg i taget, väntar {4} min mellan ändringar och stoppar av sig själv när nivån är låg i {5} min.",
