  "Wheelchair access": "Rullstolsanpassad",
  "When": "När",
  "When a driver declines or ignores an offer.": "När en förare avböjer eller ignorerar ett erbjudande.",
  "When a driver takes it, it disappears at once from every other driver's app. If that driver cancels {0} before pickup, it goes back out as {1}.{2}": "När en förare tar den försvinner den direkt från alla andra förares appar. Om den föraren avbokar {0} före upphämtningen går den ut igen som {1}.{2}",
  "When an applicant has not done their part, the app reminds them.": "När en sökande inte har gjort sin del påminner appen.",
  "When busy, collect requests for a few seconds and match them together for the best fit.": "När det är hektiskt, samla förfrågningar i några sekunder och matcha dem tillsammans för bästa passning.",
  "When drivers get paid": "När förarna får betalt",
  "When it runs {0}": "När den körs {0}",
  "When off, Show still works and is still logged, without a reason.": "När den är av fungerar Visa fortfarande och loggas, utan skäl.",
  "When published": "Vid publicering",
  "When requests per free driver reach": "När förfrågningar per ledig förare når",
  "When the admin gets an alert": "När adminen får ett larm",
  "When the driver accepted": "När föraren accepterade",
  "When the driver and rider apps ask \"Is everything OK?\". Same for every zone; the switches per zone are in Dispatch → Rules → Safety.": "När förar- och resenärsappen frågar ”Är allt ok?”. Samma för alla zoner; brytarna per zon finns i Trafikledning → Regler → Säkerhet.",
  "When the driver can get the next trip while driving a rider. Each limit has its own switch; with both off, offers can come on the whole last leg.": "När föraren kan få nästa resa medan hen kör en resenär. Varje gräns har sin egen brytare; med båda av kan erbjudanden komma under hela sista etappen.",
  "When the driver opens the radar screen.": "När föraren öppnar radarskärmen.",
