  "Small offer cards while the driver is on the map screen. Independent of the full-screen list.": "Små erbjudandekort när föraren är på kartskärmen. Oberoende av helskärmslistan.",
  "The other dispatch rules: best driver, rider waiting, rides and stops, drivers, safety, alerts": "De andra dispatchreglerna: bästa förare, väntande resenär, resor och stopp, förare, säkerhet, larm",
  "Time on the radar{0}": "Tid på radarn{0}",
  "Two radar screens, each with its own limit: the full-screen list and the offer cards over the map. The driver app detects whether the car is moving.": "Två radarskärmar, var och en med egen gräns: helskärmslistan och erbjudandekorten över kartan. Förarappen känner av om bilen rör sig.",
  "When the driver opens the radar screen: a list of the rides on the radar.": "När föraren öppnar radarskärmen: en lista över resorna på radarn.",
  "When the time runs out and nobody accepted, the same radar goes out again until an admin stops it or a driver accepts.": "När tiden går ut och ingen har accepterat skickas samma radar igen tills en admin stoppar den eller en förare accepterar.",
  "While the car is moving the driver cannot open the list. It opens again as soon as the car stops.": "När bilen rör sig kan föraren inte öppna listan. Den öppnas igen så snart bilen stannar.",
  "rule {0}: {1} s, up to {2} drivers": "regel {0}: {1} s, upp till {2} förare",
  "sends again by itself": "skickar igen av sig själv",
  "sends once": "skickar en gång",
  "{0} Back to radar zones": "{0} Tillbaka till radarzoner",
  "{0} Dispatch rules": "{0} Dispatchregler",
  "{0} Draw it on the map like a zone: shape, rectangle, circle or free hand. It belongs to {1}. Radar zones may overlap; a radar sent to this one goes to the free drivers inside it at that moment.": "{0} Rita den på kartan som en zon: form, rektangel, cirkel eller frihand. Den hör till {1}. Radarzoner får överlappa; en radar som skickas till den här går till de lediga förarna inne i den just då.",
  "{0} Full-screen radar list": "{0} Radarlista i helskärm",
  "{0} How Radar, Exclusive and reservation offers work is set in {1}.": "{0} Hur Radar-, Exklusiv- och bokningserbjudanden fungerar ställs in i {1}.",
  "{0} New radar zone": "{0} Ny radarzon",
  "{0} Offer cards on the map": "{0} Erbjudandekort på kartan",
  "{0} Radar zone rules · all of {1}": "{0} Radarzonsregler · hela {1}",
  "{0} Radar zones in {1}": "{0} Radarzoner i {1}",
  "{0} Radar · Exclusive · Reservations": "{0} Radar · Exklusiv · Bokningar",
  "{0} The app waits about 10 seconds before switching between stopped and driving, so a traffic light does not flip the cards. Cards never pop over the navigation while driving.": "{0} Appen väntar cirka 10 sekunder innan den växlar mellan stillastående och körning, så att ett trafikljus inte får korten att hoppa. Kort dyker aldrig upp över navigeringen under körning.",
  "{0} The best driver, drivers finishing a ride nearby and favourite drivers are in {1}. What the offer card shows is in {2}.": "{0} Bästa förare, förare som avslutar en resa i närheten och favoritförare finns i {1}. Vad erbjudandekortet visar finns i {2}.",
  "{0} Wider area: the search distance steps in {1}. Which mode runs, by time or how busy, is in {2}.": "{0} Större område: sökavståndets steg finns i {1}. Vilket läge som körs, efter tid eller hur upptaget det är, finns i {2}.",
  "{0} km² · {1}": "{0} km² · {1}",
  "{0} km² · {1} free driver{2} inside right now": "{0} km² · {1} ledig{2} förare inne just nu",
  "{0} moved": "{0} flyttat",
