  "Events: a concert or a match": "Evenemang: en konsert eller en match",
  "Save drivers as a group, then send a waiting ride to the group or put it on the group's radar from Live or the Dashboard.": "Spara förare som en grupp, skicka sedan en väntande resa till gruppen eller lägg den på gruppens radar från Live eller Översikten.",
  "No rule yet: every radar zone uses its zone's normal radar time and drivers.": "Ingen regel ännu: varje radarzon använder sin zons vanliga radartid och förare.",
  "the zone's normal radar time and drivers": "zonens vanliga radartid och förare",
  "Radar · Exclusive · Reservations › Radar": "Radar · Exklusiv · Bokningar › Radar",
