  "Drivers for the radar": "Förare för radarn",
  "Ends the search. The rider is told that no driver was found.": "Avslutar sökningen. Resenären får veta att ingen förare hittades.",
  "Exclusive offer to the nearest free driver who can drive {0}: {1}, {2} km": "Exklusivt erbjudande till närmaste lediga förare som kan köra {0}: {1}, {2} km",
  "Exclusive offer to {0}": "Exklusivt erbjudande till {0}",
  "Exclusive to nearest": "Exklusivt till närmaste",
  "Handle opens the same panel as on the Dashboard: Exclusive (one offer to one nearby driver) and Radar (a radar zone, whole zones, a driver group or drivers you tick, up to 10), again and again until one accepts. Exclusive to nearest offers the ride to the nearest free driver now.": "Hantera öppnar samma panel som på översikten: Exklusivt (ett erbjudande till en förare nära) och Radar (en radarzon, hela zoner, en förargrupp eller förare du bockar för, upp till 10), om och om igen tills någon tar den. Exklusivt till närmaste erbjuder resan till närmaste lediga förare nu.",
  "Max drivers who can see it": "Max antal förare som ser den",
  "Nearby driver": "Förare nära",
  "Nearest free drivers": "Närmaste lediga förare",
  "Next to it": "Intill",
  "No free driver in the list above.": "Ingen ledig förare i listan ovan.",
  "No free driver inside right now. The radar still goes out and reaches drivers who come in.": "Ingen ledig förare inne just nu. Radarn skickas ändå och når förare som kommer in.",
  "No radar zone here yet. {0}": "Ingen radarzon här ännu. {0}",
  "Or tick drivers yourself": "Eller bocka för förare själv",
  "See the active drivers near the pickup: send an exclusive offer or a radar": "Se aktiva förare nära upphämtningen: skicka ett exklusivt erbjudande eller en radar",
  "Send exclusive offer": "Skicka exklusivt erbjudande",
  "Send the ride to a radar zone, to whole zones or to a driver group; or tick the drivers yourself. The first to accept takes it.": "Skicka resan till en radarzon, till hela zoner eller till en förargrupp; eller bocka för förarna själv. Den som tar den först får den.",
  "The rider only sees “Searching” until a driver accepts. Exclusive: one offer to one driver. Radar: several drivers at once, up to {0}. Repeat until someone accepts.": "Resenären ser bara ”Söker” tills en förare tar resan. Exklusivt: ett erbjudande till en förare. Radar: flera förare samtidigt, upp till {0}. Upprepa tills någon tar den.",
  "This zone + zones around": "Denna zon + zoner runt om",
  "This zone only": "Bara denna zon",
  "Which radar zones": "Vilka radarzoner",
  "the radar for {0}": "radarn för {0}",
  "{0} Active drivers near the pickup. Click a driver’s name to send the exclusive offer; the driver has {1} s to accept.": "{0} Aktiva förare nära upphämtningen. Klicka på en förares namn för att skicka det exklusiva erbjudandet; föraren har {1} s att svara.",
  "{0} Cancel request": "{0} Avbryt begäran",
  "{0} Exclusive to nearest offers the ride to the nearest free driver who is allowed to drive the requested category. Handle opens Exclusive and Radar, the same panel as in Dispatch.": "{0} Exklusivt till närmaste erbjuder resan till närmaste lediga förare som får köra den begärda kategorin. Hantera öppnar Exklusivt och Radar, samma panel som i Dispatch.",
  "{0} Exclusive · one driver at a time": "{0} Exklusivt · en förare i taget",
